class Solution {
  public int sumOfGoodNumbers(int[] nums, int k) {
    int n = nums.length, sum = 0;
    for (int i = 0; i < n; i++) {
      boolean good = (i - k < 0 || nums[i] > nums[i - k]) && (i + k >= n || nums[i] > nums[i + k]);
      if (good) sum += nums[i];
    }
    return sum;
  }
}
